items=[]
for a,b,k,n,s,la,lo,d,t,src,tr in I:
    o={"a":a,"b":b,"kind":k,"name":n,"side":s,"lat":la,"lon":lo,"distanceM":d,"text":t,"source":src}
    if tr: o["textReverse"]=tr
    assert ("{side}" in t)==(s is not None),n
    items.append(o)
data={"about":"Trainchecker 'Your train passes near…'. One item per stretch between neighbouring stations. side is the side of the train when travelling from a to b (facing forwards); swap left/right for b to a. text has {side} for 'left'/'right'; textReverse, where present, replaces text for b to a. England only. Researched in a Claude chat, November 22nd 2026; every fact checked against source.",
 "lines":[{"name":"London Paddington to Bristol Temple Meads via Bath","osmRelation":183757,"stations":["PAD","AML","EAL","WEA","HAN","STL","HAY","WDT","IVR","LNY","SLO","BNM","TAP","MAI","TWY","RDG","TLH","PAN","GOR","CHO","DID","SWI","CPM","BTH","OLF","KYN","BRI"]}],
 "items":items}
